ection class="content-card table-card"><span class="eyebrow">HISTORY</span><h2>Recent reservations</h2><?php $history=db()->query("SELECT r.*,t.table_number FROM reservations r LEFT JOIN restaurant_tables t ON t.id=r.table_id WHERE r.status<>'Pending' ORDER BY r.created_at DESC LIMIT 30")->fetchAll();foreach($history as $r): ?><div class="reservation-history"><span><?= date('M j · g:i A',strtotime($r['reservation_date'].' '.$r['reservation_time'])) ?></span><b><?= e($r['guest_name']) ?> · <?= (int)$r['guests'] ?> guests</b><span><?= e($r['table_number']??'—') ?></span><span class="status-pill status-<?= strtolower($r['status']) ?>"><?= e($r['status']) ?></span></div><?php endforeach; ?></section><?php endif; ?>
<?php if($tab==='settings'&&$isAdmin):$closed=array_map('intval',array_filter(explode(',',setting('closed_days'))));?><section class="content-card settings-card"><span class="eyebrow">WHEN THE DOOR IS OPEN</span><h2>Opening hours & closed days</h2><p class="muted">Customers can only request tables inside these hours.</p><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="settings"><div class="form-row"><label>Opens at<input type="time" name="opening_time" value="<?= e(setting('opening_time','11:00')) ?>" required></label><label>Closes at<input type="time" name="closing_time" value="<?= e(setting('closing_time','22:00')) ?>" required></label></div><label>Hours label for customers<input name="opening_label" value="<?= e(setting('opening_hours','Daily · 11:00 AM – 10:00 PM')) ?>"></label><fieldset class="closed-days"><legend>Closed days</legend><?php foreach(['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'] as $i=>$day): ?><label><input type="checkbox" name="closed_days[]" value="<?= $i ?>" <?= in_array($i,$closed,true)?'checked':'' ?>> <?= $day ?></label><?php endforeach; ?></fieldset><label>Delivery fee (MMK)<input type="number" min="0" step="1" name="delivery_fee" value="<?= e(setting('delivery_fee','1500')) ?>"></label><button class="button button-dark">Save hours & settings</button></form></section><?php endif; ?>
<?php if($tab==='reports'&&$isAdmin):$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$report=db()->prepare("SELECT COUNT(*) orders,COALESCE(SUM(total),0) revenue FROM orders WHERE DATE(created_at) BETWEEN ? AND ?");$report->execute([$from,$to]);$summary=$report->fetch();$rows=db()->prepare("SELECT order_number,created_at,status,total FROM orders WHERE DATE(created_at) BETWEEN ? AND ? ORDER BY created_at DESC LIMIT 200");$rows->execute([$from,$to]);?><section class="content-card report-card"><form method="get" class="report-filters"><input type="hidden" name="tab" value="reports"><label>From<input type="date" name="from" value="<?= e($from) ?>"></label><label>To<input type="date" name="to" value="<?= e($to) ?>"></label><button class="button button-dark button-small">Update</button><a class="button button-outline-dark button-small" href="?tab=reports&export=1&from=<?= e($from) ?>&to=<?= e($to) ?>">Export CSV ↓</a></form><div class="report-summary"><span><small>ORDERS</small><b><?= (int)$summary['orders'] ?></b></span><span><small>REVENUE</small><b><?= money($summary['revenue']) ?></b></span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Order</th><th>Placed</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['order_number']) ?></td><td><?= date('M j, Y g:i A',strtotime($r['created_at'])) ?></td><td><span class="status-pill status-<?= strtolower($r['status']) ?>"><?= e($r['status']) ?></span></td><td><?= money($r['total']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
</div></section>
